// Parse do CSV baixado pelo HTTP Request
const rawCsv = $input.first().json.data || $input.first().json.body || $input.first().text || '';
const linhas = rawCsv.trim().split(/\r?\n/);
const cabecalho = linhas[0].split(',').map(c => c.trim().toLowerCase());
const investimentos = [];

for (let i = 1; i < linhas.length; i++) {
  const linha = linhas[i].trim();
  if (!linha) continue;
  const colunas = linha.split(',').map(c => c.trim());
  const item = {};
  cabecalho.forEach((col, idx) => {
    item[col] = colunas[idx] || '';
  });
  item.minimo_valor = parseFloat(item.minimo.replace(/[^0-9.]/g, '')) || 0;
  investimentos.push(item);
}

return [{ json: { investimentos: investimentos } }];

// Normaliza e consolida dados vindos do Merge (Clientes do Webhook + Investimentos do CSV)
const dados = $input.first().json;

let clientes = [];
if (dados.body && Array.isArray(dados.body.clientes)) {
  clientes = dados.body.clientes;
} else if (dados.body && Array.isArray(dados.body)) {
  clientes = dados.body;
} else if (Array.isArray(dados.clientes)) {
  clientes = dados.clientes;
} else if (Array.isArray(dados)) {
  clientes = dados;
} else if (dados.body) {
  clientes = [dados.body];
}

const investimentos = dados.investimentos || [];

return [{
  json: {
    clientes: clientes,
    investimentos: investimentos,
    total_clientes: clientes.length,
    total_investimentos: investimentos.length
  }
}];

// Cruza cada cliente com os investimentos compativeis e expande para 10 itens
const dados = $input.first().json;
const clientes = dados.clientes || [];
const investimentos = dados.investimentos || [];

function parseSaldo(saldoStr) {
  if (typeof saldoStr === 'number') return saldoStr;
  if (!saldoStr) return 0;
  const limpo = saldoStr.replace(/[^0-9,-]/g, '').replace(/\./g, '').replace(',', '.');
  return parseFloat(limpo) || 0;
}

const itensSeparados = clientes.map(cliente => {
  const saldoNum = parseSaldo(cliente.saldo);
  const perfil = (cliente.perfil || '').trim();

  // Filtra produtos compativeis ao perfil
  const produtosPerfil = investimentos.filter(inv =>
    inv.perfil.toLowerCase() === perfil.toLowerCase()
  );

  // Filtra produtos que cabem no saldo
  const produtosAcessiveis = produtosPerfil.filter(inv => saldoNum >= (inv.minimo_valor || 0));
  const recomendados = produtosAcessiveis.length > 0 ? produtosAcessiveis : produtosPerfil;

  const listaFormatada = recomendados.map(p => `• ${p.produto} | Mínimo: R$ ${p.minimo} | Rentabilidade: ${p.rentabilidade}`).join('\n');

  // Prompt estruturado para o modelo de IA (Message a model)
  const promptIA = `Você é um consultor financeiro de alto padrão. Crie uma mensagem personalizada, elegante e acolhedora em português para o cliente:
Nome: ${cliente.nome}
Perfil de Risco: ${perfil}
Saldo Disponível: ${cliente.saldo}
Produtos Recomendados:
${listaFormatada}

Instruções:
1. Cumprimente pelo primeiro nome.
2. Explique com simpatia por que essas opções combinam com o perfil ${perfil}.
3. Apresente os ativos recomendados com clareza.
4. Finalize com um convite cordialmente profissional para dar início ao aporte.`;

  // Mensagem padronizada de fallback caso o nó de IA nao tenha credencial ativa
  const mensagemFallback = `Olá, ${cliente.nome.split(' ')[0]}! Notamos que seu perfil de investidor é ${perfil}. Com base no seu saldo disponível de ${cliente.saldo}, recomendamos as seguintes opções:\n${listaFormatada}\nConte com nossa assessoria para começar a investir com segurança!`;

  return {
    json: {
      ...cliente,
      saldo_numerico: saldoNum,
      produtos_recomendados: recomendados,
      prompt: promptIA,
      mensagem_fallback: mensagemFallback
    }
  };
});

return itensSeparados;

// Extrai a resposta da IA (ou usa o fallback) e formata os dados para o envio do email
const item = $input.item.json;

const textoGerado = item.message?.content || item.response?.text || item.text || item.mensagem_fallback;
const primeiroNome = (item.nome || 'Cliente').split(' ')[0];

return {
  json: {
    nome: item.nome,
    email: item.email,
    perfil: item.perfil,
    saldo: item.saldo,
    produtos_recomendados: item.produtos_recomendados,
    mensagem_final: textoGerado,
    assunto_email: `Recomendações exclusivas de investimentos para ${primeiroNome}`,
    corpo_email: textoGerado,
    enviar_email: Boolean(item.email && item.email.includes('@')),
    processado_em: new Date().toISOString()
  }
};

